     1	import { type Item, insuranceSumOf } from "./claim-office.js";
     2	
     3	const DEDUCTIBLE_PER_DAMAGE_ENTRY = 100;
     4	const PAYOUT_CAP_MULTIPLE = 2;
     5	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
     6	const HIGH_ENCHANTMENT_REIMBURSEMENT_SHARE = 0.5;
     7	const UNREDUCED_REIMBURSEMENT_SHARE = 1;
     8	
     9	export interface Damage {
    10	  readonly itemType: string;
    11	  readonly amount: number;
    12	}
    13	
    14	export interface Incident {
    15	  readonly cause: string;
    16	  readonly damages: readonly Damage[];
    17	}
    18	
    19	export interface Policy {
    20	  readonly items: readonly Item[];
    21	  readonly insuranceSum: number;
    22	  remainingCap: number;
    23	}
    24	
    25	export interface ClaimSettlement {
    26	  readonly payout: number;
    27	  readonly remainingCap: number;
    28	}
    29	
    30	// A damage entry names an insured item by type; the clauses that govern the
    31	// payout are properties of that insured item, not of the damage report. This
    32	// resolves which clauses govern a damage, not which physical item was destroyed:
    33	// with two swords insured, two sword damage entries resolve to the same insured
    34	// item, which is right because the clauses read only the item's attributes and
    35	// alike items share them. Counting entries against items insured is a separate
    36	// rejection rule.
    37	function damagedItemFor(policy: Policy, damage: Damage): Item {
    38	  const damagedItem = policy.items.find((item) => item.type === damage.itemType);
    39	  if (damagedItem === undefined) {
    40	    throw new Error(`damaged item ${damage.itemType} is not covered by the policy`);
    41	  }
    42	  return damagedItem;
    43	}
    44	
    45	function roundPayoutInOfficesFavour(payout: number): number {
    46	  return Math.floor(payout);
    47	}
    48	
    49	export function policyFor(items: readonly Item[]): Policy {
    50	  const insuranceSum = insuranceSumOf(items);
    51	  return { items, insuranceSum, remainingCap: insuranceSum * PAYOUT_CAP_MULTIPLE };
    52	}
    53	
    54	// The share of the damage amount the office reimburses, decided by the clauses
    55	// that the damaged item triggers. Damage to an item with enchantment level >= 8
    56	// is reimbursed at 50 %; with no clause reducing it, the whole amount is
    57	// reimbursable. The share is taken before the deductible.
    58	//
    59	// There is deliberately no dragon-material branch here, and adding one would be
    60	// a mistake. The spec's clause "damage to items made of dragon material is fully
    61	// reimbursed" asks for exactly the share this function already yields by default,
    62	// so on its own it is indistinguishable from no clause at all (dragon sword,
    63	// enchantment 5, damage 800 -> 800 - 100 = 700, identical to a steel sword). The
    64	// only case where it meets another clause is enchantment >= 8, and there the spec
    65	// says the 50 % rule wins (dragon sword, enchantment 8 or 9, damage 1000 -> 400).
    66	// So the clause never changes a payout: it is subsumed by the unreduced share and
    67	// loses every conflict. `Item.material` is read by no rule for that reason.
    68	function reimbursableShareOf(damagedItem: Item): number {
    69	  return (damagedItem.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL
    70	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_SHARE
    71	    : UNREDUCED_REIMBURSEMENT_SHARE;
    72	}
    73	
    74	// One entry of the incident's `damages` array is one damage, and each one bears
    75	// its own deductible -- a single dragon attack that damages a sword and an amulet
    76	// deducts 100 G twice, not once.
    77	function reimbursementFor(damage: Damage, damagedItem: Item): number {
    78	  return damage.amount * reimbursableShareOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE_ENTRY;
    79	}
    80	
    81	// Summing per entry is what makes the deductible per-entry: the incident as a
    82	// whole is never the unit the deductible is charged against.
    83	function desiredReimbursementFor(policy: Policy, incident: Incident): number {
    84	  return incident.damages.reduce(
    85	    (sum, damage) => sum + reimbursementFor(damage, damagedItemFor(policy, damage)),
    86	    0,
    87	  );
    88	}
    89	
    90	// The cap limits what a single claim pays out, and every payout consumes it:
    91	// successive claims against the same policy share one cap.
    92	function payoutLimitedToRemainingCap(desiredReimbursement: number, remainingCap: number): number {
    93	  return Math.min(desiredReimbursement, remainingCap);
    94	}
    95	
    96	function consumeCap(policy: Policy, payout: number): void {
    97	  policy.remainingCap -= payout;
    98	}
    99	
   100	export function settle(policy: Policy, incident: Incident): ClaimSettlement {
   101	  const payout = roundPayoutInOfficesFavour(
   102	    payoutLimitedToRemainingCap(desiredReimbursementFor(policy, incident), policy.remainingCap),
   103	  );
   104	  consumeCap(policy, payout);
   105	  return { payout, remainingCap: policy.remainingCap };
   106	}
